<script type="application/ld+json">
{"@context": "https://schema.org", "@type": "FAQPage", "mainEntity": [{"@type": "Question", "name": "Когда заказчик обязан установить обеспечение заявки?", "acceptedAnswer": {"@type": "Answer", "text": "При проведении конкурентных способов. Заказчик вправе не устанавливать обеспечение, если начальная (максимальная) цена контракта не превышает 1 млн ₽. Государственные и муниципальные учреждения обеспечение по своим заявкам не предоставляют."}}, {"@type": "Question", "name": "Какой размер обеспечения заявки по 44-ФЗ?", "acceptedAnswer": {"@type": "Answer", "text": "Если НМЦК до 20 млн ₽ — от 0,5% до 1% НМЦК; если более 20 млн ₽ — от 0,5% до 5% НМЦК. Для предприятий УИС и организаций инвалидов — 0,5% НМЦК. Конкретный процент в этих границах указывает заказчик в извещении."}}, {"@type": "Question", "name": "Какими способами вносят обеспечение заявки?", "acceptedAnswer": {"@type": "Answer", "text": "Денежными средствами или независимой гарантией по статье 45. При электронных процедурах деньги блокируются на специальном счёте в банке из перечня Правительства, либо предоставляется независимая гарантия из реестра в ЕИС."}}, {"@type": "Question", "name": "Что такое спецсчёт и как работает блокировка?", "acceptedAnswer": {"@type": "Answer", "text": "Это счёт участника в уполномоченном банке. При подаче заявки банк блокирует сумму обеспечения — деньги остаются на счёте участника, но он временно не может ими распоряжаться. На средства начисляются проценты, взыскание по ним не обращается."}}, {"@type": "Question", "name": "Когда обеспечение заявки возвращают?", "acceptedAnswer": {"@type": "Answer", "text": "При отклонении или отзыве заявки, заключении контракта, отмене закупки и в ряде других случаев. Оператор площадки направляет в банк команду прекратить блокировку, как правило, в течение часа с момента наступления случая."}}, {"@type": "Question", "name": "Когда обеспечение заявки не возвращают?", "acceptedAnswer": {"@type": "Answer", "text": "При уклонении победителя от заключения контракта и включении его в реестр недобросовестных поставщиков: деньги перечисляются в бюджет, по гарантии заказчик предъявляет требование об уплате. Также удерживается обеспечение по правилу трёх заявок."}}, {"@type": "Question", "name": "Чем обеспечение заявки отличается от обеспечения исполнения контракта?", "acceptedAnswer": {"@type": "Answer", "text": "Обеспечение заявки страхует этап торгов (статья 44), а обеспечение исполнения — надлежащее исполнение контракта (статья 96). Это разные инструменты с разными суммами и сроками."}}, {"@type": "Question", "name": "Какой срок действия независимой гарантии для заявки?", "acceptedAnswer": {"@type": "Answer", "text": "Не менее месяца с даты окончания срока подачи заявок. Для электронных процедур гарантия должна быть включена в реестр независимых гарантий в ЕИС."}}]}
</script>
<script type="application/ld+json">
{"@context": "https://schema.org", "@type": "HowTo", "name": "Как внести обеспечение заявки по 44-ФЗ", "inLanguage": "ru-RU", "step": [{"@type": "HowToStep", "position": 1, "name": "Прочитать извещение о закупке", "text": "Найти в извещении размер обеспечения заявки и допустимые способы его предоставления."}, {"@type": "HowToStep", "position": 2, "name": "Посчитать сумму обеспечения", "text": "Умножить начальную (максимальную) цену контракта на установленный процент (от 0,5% до 5%)."}, {"@type": "HowToStep", "position": 3, "name": "Открыть специальный счёт", "text": "Открыть спецсчёт в банке из перечня Правительства, у которого есть соглашения с операторами электронных площадок."}, {"@type": "HowToStep", "position": 4, "name": "Пополнить специальный счёт", "text": "Обеспечить наличие незаблокированной суммы обеспечения на счёте к моменту подачи заявки."}, {"@type": "HowToStep", "position": 5, "name": "Подать заявку на участие", "text": "Подать заявку через электронную площадку; подача означает согласие на блокировку, и банк блокирует средства."}, {"@type": "HowToStep", "position": 6, "name": "Дождаться итогов процедуры", "text": "После завершения процедуры блокировку прекращают; при заключении контракта средства разблокируют."}]}
</script>
