{"@context": "https://schema.org", "@type": "DefinedTermSet", "name": "Глоссарий: обеспечение заявки по 44-ФЗ", "inLanguage": "ru-RU", "hasDefinedTerm": [{"@type": "DefinedTerm", "name": "Обеспечение заявки", "description": "Сумма, которой участник закупки подтверждает серьёзность намерений; регулируется статьёй 44 44-ФЗ."}, {"@type": "DefinedTerm", "name": "НМЦК", "description": "Начальная (максимальная) цена контракта, от которой считается размер обеспечения заявки."}, {"@type": "DefinedTerm", "name": "Специальный счёт", "description": "Счёт участника в банке из перечня Правительства, на котором блокируются средства для обеспечения заявки."}, {"@type": "DefinedTerm", "name": "Блокировка средств", "description": "Временное ограничение права распоряжаться суммой обеспечения на спецсчёте; не является списанием."}, {"@type": "DefinedTerm", "name": "Независимая гарантия", "description": "Обязательство гаранта выплатить заказчику сумму обеспечения; альтернатива денежному обеспечению (статья 45)."}, {"@type": "DefinedTerm", "name": "Реестр недобросовестных поставщиков (РНП)", "description": "Реестр, включение в который при уклонении влечёт удержание обеспечения заявки."}, {"@type": "DefinedTerm", "name": "Правило трёх заявок", "description": "Удержание обеспечения каждой третьей из трёх и более несоответствующих заявок одного участника за квартал на одной площадке."}]}
